import type { MetadataRoute } from "next";

import { getSettings } from "@/features/settings/queries";

export default async function manifest(): Promise<MetadataRoute.Manifest> {
  const s = await getSettings();
  const name = s["business.name"] || "Tempe Mak Nuk";
  return {
    name,
    short_name: "Mak Nuk",
    description: "Tempe handmade dari Klaten sejak 2001. Tanpa pengawet, bersertifikat halal.",
    id: "/",
    start_url: "/",
    scope: "/",
    display: "standalone",
    lang: "id",
    background_color: "#FAF7F2",
    theme_color: "#2F4A2C",
    // PNG icons are generated by P6.3 (src/app/icon.tsx / apple-icon.tsx); only the SVG exists in public/brand.
    icons: [{ src: "/brand/favicon.svg", sizes: "any", type: "image/svg+xml", purpose: "any" }],
  };
}
